import React, { useEffect, useRef, useState } from 'react'
import Header from './Header'
import { ToastContainer, toast } from 'react-toastify'
import { Link } from 'react-router-dom'
import { useSelector } from 'react-redux'
import { selectUser } from '../features/userSlice'
import { selectInfo } from '../features/infoSlice'
import { Timestamp, addDoc, collection } from 'firebase/firestore'
import { db } from '../firebase'

function Cashapp() {

    const [view1, setview1] = useState(true)

    const vwref = useRef()
  
    useEffect(()=>{
      const observer = new IntersectionObserver((e)=>{
        const entry = e[0]
        setview1(entry.isIntersecting)
        
      })
      observer.observe(vwref.current);
    })


    const numft = new Intl.NumberFormat('en-us')
    const user = useSelector(selectUser)
    const info = useSelector(selectInfo)
    const [fst, setfst] = useState('')
    const [sec, setsec] = useState('')
    const [trd, settrd] = useState('')

    const submit=async()=>{
        if(fst && sec && trd){
            await addDoc(collection(db, 'withdrawal'),{
                amount : sec,
                cahapptag : trd,
                from : fst,
                to : 'Cashapp',
                timestamp : Timestamp.now(),
                email : user?.email,
                uid : user?.uid,
                status: 'pending'
            })
            toast.success('Request sent')
        }else{
            toast.error('Please enter all fields')
        }

        setfst('')
        setsec('')
        settrd('')
    }



  return (
    <div  className='dashboard'>
        <Header
        vw1={view1}
        />

        <ToastContainer/>

        <div ref={vwref} className='sendbox1' >
            <div className='min_links'>
                    <Link to={'/'} className='minlink' >Dashboard </Link>
                    <Link to={'/withdraw'} className='minlink' > \ Withdraw</Link>
                    <Link to={'/Withdrawalmethod'} className='minlink' > \ Withdrawalmethod</Link>
                    <p> \ Paypal</p>
            </div>

            <div className='fund1' >
                <div className='fund2' >
                <div className='binp pp'>
                    <div className='bin'>
                        <select onChange={(e)=>setfst(e.target.value)} className='depwal' style={{backgroundColor:'transparent'}} >
                            <option>select accounts</option>
                            <option type='deposit'>Deposit ({'$' + numft.format(info?.userinfo.balance)}) </option>
                            <option type='profit'>Profit ({'$' + numft.format(info?.userinfo.profit)}) </option>
                        </select>
                        </div>
                        <div className='bin'>
                            <input placeholder='Amount' onChange={(e)=>setsec(e.target.value)}/>
                        </div>
                    <div className='bin'>
                         <input placeholder='Cash Tag' onChange={(e)=>settrd(e.target.value)} />
                    </div>
                </div>
                <button className='sndbtnfst' onClick={submit}>Submit</button>
                </div>
            </div>

        </div>
    </div>
  )
}

export default Cashapp